#!/bin/bash
# Stage 1: build all caches (sequential), then E1 tuning (GPU) and E0 ML baselines (CPU) in parallel.
# Launch:  nohup bash run_stage1.sh > logs/stage1.log 2>&1 &
# Progress: tail -f logs/E1.log logs/E0.log      (do NOT edit this file while it runs)
set -u
cd "$(dirname "$0")"
mkdir -p logs
echo "[stage1] start $(date)"
python3 jobs.py cache > logs/cache.log 2>&1
echo "[stage1] caches done $(date)"
python3 jobs.py E1 --threads 2 > logs/E1.log 2>&1 &
python3 jobs.py E0 --threads 4 > logs/E0.log 2>&1 &
wait
echo "[stage1] E0 + E1 done $(date)"
